-- ===========================================================================
-- otbi-atd db/71 : AR Invoice Distribution Details - V2 -- chunked (v2 shape)
--
-- v2 2026-08-17: the OWNER REDESIGNED the saved analysis -- it now FILTERS to
-- Accounting Class IN (Revenue, Tax) + non-zero Distribution Entered Amount +
-- Natural Account Code NOT IN (120123, 120151), replaces the old Distribution
-- Cost-Center / Natural-Account code+description columns with the Cost Center
-- / Natural Account Segment Value descriptions + their DESCRIPTOR_IDOFs
-- (probed live: IDOF(description) IS the segment code, so the pairs keep
-- their old colmap headings and table columns), and adds the GL Account
-- combination, Transaction Line Type and 4 Transaction Accounting CR/DR
-- amounts (7 NEW headings -- the drift engine ALTER TABLE ADDs their columns
-- on first run). Filter kept verbatim in EVERY chunk; 15 chunks, ALL bounded
-- date ranges on the DIM "- Distribution Accounting Date"."Accounting Date"
-- (Dec-2025 x Revenue/Tax + 12 monthly 2026 + >= 2027 tail). PLAN-SHAPE LAWS
-- (probed live 2026-08-18): with the new joins, IS NULL chunks and ANY range
-- reaching pre-Dec-2025 HANG the BI server >100s even when the slice is
-- EMPTY; both guards dropped as verified-dead space (zero rows before
-- 2025-12-01; every NULL-date row fails the amount filter). min_rows 150,000
-- is the safety net if those invariants break; parallel 4; hourly; service
-- account via non-catalog source_ref. Generator / single source of truth =
-- runner/ard_def.py; v1 story in git history.
-- The original '- ALL' job stays DISABLED on its catalog source_ref (NOT
-- rebuilt for the redesign -- rebuild via the Jobs page before any re-use).
-- Rerunnable.
-- ===========================================================================
SET DEFINE OFF
SET SQLBLANKLINES ON

UPDATE prod.atd_otbi_jobs
   SET params_json = q'[{"_atd_sql_chunks": {"sql": "SET VARIABLE PREFERRED_CURRENCY='User Preferred Currency 1'; SELECT 0 s_0, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction ID\" s_1, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction Number\" s_2, \"Receivables - Transactions Real Time\".\"- Line Information\".\"Transaction Line Number\" s_3, \"Receivables - Transactions Real Time\".\"- Line Information\".\"Transaction Line Type\" s_4, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounted\" s_5, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" s_6, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Percentage\" s_7, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Date\" s_8, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Comments\" s_9, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Posting Control Id\" s_10, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"GL Posted Date\" s_11, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables  Code Combination Description\" s_12, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables Concatenated Segments\" s_13, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Account Type Code\" s_14, \"Receivables - Transactions Real Time\".\"- GL Account\".\"Account Code Combination Description\" s_15, \"Receivables - Transactions Real Time\".\"- GL Account\".\"Concatenated Segments\" s_16, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Entered Amount\" s_17, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Accounted Amount\" s_18, \"Receivables - Transactions Real Time\".\"- Transaction Accounting\".\"Accounted  Amount CR\" s_19, \"Receivables - Transactions Real Time\".\"- Transaction Accounting\".\"Accounted Amount DR\" s_20, \"Receivables - Transactions Real Time\".\"- Transaction Accounting\".\"Entered Amount CR\" s_21, \"Receivables - Transactions Real Time\".\"- Transaction Accounting\".\"Entered Amount DR\" s_22, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Ledger Currency\" s_23, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency Name\" s_24, DESCRIPTOR_IDOF(\"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency Name\") s_25, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Update Date\" s_26, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By\" s_27, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By User Name\" s_28, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By User Name\" s_29, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Creation Date\" s_30, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By\" s_31, DESCRIPTOR_IDOF(\"Receivables - Transactions Real Time\".\"- Cost Center Segment Value\".\"Cost Center Description\") s_32, \"Receivables - Transactions Real Time\".\"- Cost Center Segment Value\".\"Cost Center Description\" s_33, DESCRIPTOR_IDOF(\"Receivables - Transactions Real Time\".\"- Natural Account Segment Value\".\"Account Description\") s_34, \"Receivables - Transactions Real Time\".\"- Natural Account Segment Value\".\"Account Description\" s_35 FROM \"Receivables - Transactions Real Time\" WHERE (\"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" IN ('Revenue', 'Tax') AND \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Entered Amount\" IS NOT NULL AND \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Entered Amount\" <> 0 AND \"Receivables - Transactions Real Time\".\"- Natural Account Segment Value\".\"Account Code\" NOT IN ('120123', '120151')) AND ({chunk})", "chunks": ["\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Revenue'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Tax'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-02-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-02-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-03-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-03-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-04-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-04-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-05-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-05-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-06-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-06-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-07-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-07-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-08-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-08-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-09-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-09-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-10-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-10-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-11-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-11-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-12-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2027-01-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2027-01-01'"], "headers": {"#2": "Transaction ID", "#3": "Transaction Number", "#4": "Transaction Line Number", "#5": "Transaction Line Type", "#6": "Accounted", "#7": "Accounting Class", "#8": "Distribution Percentage", "#9": "Accounting Date", "#10": "Distribution Comments", "#11": "Posting Control Identifier", "#12": "Posted Date", "#13": "Receivables  Code Combination Description", "#14": "Receivables Concatenated Segments", "#15": "Account Type Code", "#16": "GL Account Combination Description", "#17": "GL Concatenated Segments", "#18": "Distribution Entered Amount", "#19": "Distribution Accounted Amount", "#20": "Accounted Amount CR", "#21": "Accounted Amount DR", "#22": "Entered Amount CR", "#23": "Entered Amount DR", "#24": "Ledger Currency", "#25": "Document Currency Name", "#26": "Document Currency", "#27": "Invoice Last Update Date", "#28": "Last Updated By", "#29": "Last Updated By User Name", "#30": "Created By User Name", "#31": "Creation Date", "#32": "Created By", "#33": "Distribution Cost Center Code", "#34": "Distribution Cost Center Description", "#35": "Distribution Natural Account Code", "#36": "Distribution Natural Account Description"}, "min_rows": 150000, "retries": 1, "parallel": 4}}]',
       source_ref = 'chunked-sql: Receivables - Transactions Real Time (AR distributions, 15 chunks)',
       frequency_minutes = 60,
       enabled = 'Y',
       requested_by = NULL
 WHERE job_name = 'AR Invoice Distribution Details - V2';

-- the original personal-account job: catalog source_ref, DISABLED fallback
UPDATE prod.atd_otbi_jobs
   SET enabled = 'N',
       requested_by = NULL
 WHERE job_name = 'AR Invoice Distribution Details - ALL';

COMMIT;

SELECT job_name, enabled, frequency_minutes,
       CASE WHEN params_json IS NULL THEN 'NONE'
            WHEN params_json IS JSON THEN 'VALID' ELSE 'BAD' END js
  FROM prod.atd_otbi_jobs
 WHERE job_name LIKE 'AR Invoice Distribution Details%';
